interface Greeting { String text(); }
class CasualGreeting implements Greeting {
    public String text() { return "Добрый день"; }
}
class Controller {
    private final Greeting greeting;
    Controller(Greeting greeting) { this.greeting = greeting; }
    String message() { return greeting.text(); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println(new Controller(new CasualGreeting()).message());
        java.util.Map<String, String> routes = java.util.Map.of("GET /ping", "pong");
        System.out.println(routes.get("GET /ping"));
    }
}
